{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "INS018_055, a fluorophenyl-pyrazole-piperazine amide kinase inhibitor structurally similar to the query, showed good oral bioavailability in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Basmisanil, containing a fluorophenyl heteroaromatic amide scaffold, had an absolute oral bioavailability of approximately 75% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "A fluorophenyl piperidine-containing fused heteroaromatic analogue showed 83% absolute oral bioavailability in healthy volunteers, indicating limited first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Tofacitinib, a heteroaromatic amide kinase inhibitor, has an absolute oral bioavailability of approximately 74% in humans, supporting high F for this compound class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Brequinar, a fluorophenyl heteroaromatic compound, showed >90% oral bioavailability in cancer patients, demonstrating that similar lipophilic aromatic structures can be very well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Darapladib, a large lipophilic amide with fluorophenyl and heteroaromatic features, had only 12% absolute oral bioavailability in humans, providing a counterexample where poor absorption/first-pass metabolism limits F.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C21"],
      "claim": "Ganciclovir has low oral bioavailability of 6–9% in humans, but its very polar, non-lipophilic structure is not closely transferable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a moderately lipophilic, heteroaromatic amide/piperazine-containing kinase-inhibitor-like molecule. Most structurally relevant analogues with human oral bioavailability data show high F (67–90%), while the main low-F analogue, darapladib, is larger and more lipophilic with different solubility liabilities. On balance, the transferable evidence supports F ≥ 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "Morgan similarities to all evidence molecules are low (~0.19–0.22), limiting transferability.",
    "No information on aqueous solubility, permeability, or first-pass metabolism for the query.",
    "Formulation-dependent effects on oral absorption are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

